        {
            if (VerifySaveData(Dpr.NX.SaveSystem.GetLoadedData()))
            {
                byte[] data = Dpr.NX.SaveSystem.GetLoadedData();
                // the four version bytes are read as one 32-bit load after a single bounds check (@02ceb930..02ceb93c)
                int version = data[0] | (data[1] << 8) | (data[2] << 16) | (data[3] << 24);
                if (version < SaveData.CURRENT_VERSION_29)
                    Array.Clear(data, SaveData.GMS_WORK_ADDR, SaveData.GMS_WORK_SIZE);

                LoadBytes(data, ref _saveData);
                _loadResult = LoadResult.SUCCESS;
            }
            else
            {
                _loadResult = LoadResult.CORRUPTED;
            }
        }
        else
        {
            _loadResult = Dpr.NX.SaveSystem.SaveDataExists() ? LoadResult.FAILED : LoadResult.NOT_EXIST;
        }

        _isBackupSave = false;
        return true;
    }
	protected override bool CustomSaveOperation() {
#if !SWITCH
        _saveData.playerData.mystatus.rom_code = global::PcPlatform.PcConfig.RomCode;
#else
        _saveData.playerData.mystatus.rom_code = 0;
#endif
        ToBytes(_saveData, ref _writeSrcBuffer);
        makeSaveDataHash(ref _writeSrcBuffer);
        Dpr.NX.SaveSystem.Save(_writeSrcBuffer, _isMainSave, _isBackupSave);
        // one strh of 0x0001 over _isMainSave / _isBackupSave (@02cebfcc)
        _isMainSave = true;
        _isBackupSave = false;
        return true;
    }
	protected override bool CustomLoadAsyncOperation() {
        Dpr.NX.SaveSystem.LoadAsync(_isBackupSave, OnPostLoadAsync);
        _isBackupSave = false;
        return true;
    }
	private void OnPostLoadAsync(bool result) {
        if (result)
        {
            if (VerifySaveData(Dpr.NX.SaveSystem.GetLoadedData()))
            {
                // shipped: no GMS-area clear for old versions on the async path (CustomLoadOperation has it)
                LoadBytes(Dpr.NX.SaveSystem.GetLoadedData(), ref _saveData);
                OnPostLoad();
                _loadResult = LoadResult.SUCCESS;
            }
            else
            {
                _loadResult = LoadResult.CORRUPTED;
            }
        }
        else
        {
            _loadResult = Dpr.NX.SaveSystem.SaveDataExists() ? LoadResult.FAILED : LoadResult.NOT_EXIST;
        }
    }
	protected override bool CustomSaveAsyncOperation() {
        OnPreSave();
#if !SWITCH
        _saveData.playerData.mystatus.rom_code = global::PcPlatform.PcConfig.RomCode;
#else
        _saveData.playerData.mystatus.rom_code = 0;
#endif
        ToBytes(_saveData, ref _writeSrcBuffer);
        makeSaveDataHash(ref _writeSrcBuffer);
        Dpr.NX.SaveSystem.SaveAsync(_writeSrcBuffer, _isMainSave, _isBackupSave);
        _isMainSave = true;
        _isBackupSave = false;
        return true;
    }
	protected override void OnPostLoad() {
        EvDataManager.IsFirstInitializedAfterSaveDataLoad = false;

        if (_saveData.version < SaveData.CURRENT_VERSION_20)
        {
            Initialization();
            Save(false);
        }

        if (_saveData.version < SaveData.CURRENT_VERSION)
            TakeOverOldVersion();

        if (DataManager.IsLoaded())
            OnPostLoad_NeedMD();
        else
            DataManager.onPostLoadData += OnPostLoad_NeedMD;
    }
