	public static void DataSave(bool isAsync = false, bool writeMain = true, bool writeBackup = false) {
        instance._isMainSave = writeMain;
        instance._isBackupSave = writeBackup;

        if (FieldManager.fwMng != null)
            FieldManager.fwMng.UpdatePartnerPokeIndex();

        PlayReportManager.SaveRecordDataEvent();

        GMTIME saveTime = SystemTimeWork.GetSaveTime();
        if (uniqueID != 0)
            SystemTimeWork.SetSaveTime();

        if (Dpr.UnderGround.UgFieldManager.isInstantiated)
            Dpr.UnderGround.UgFieldManager.Instance.SAVE_POKE();

        Save(isAsync);

        if (!writeMain && writeBackup)
        {
            // get_SystemData / set_SystemData inlined (flag 0x4edbec9 @02ced3c8): backup-only saves stamp the earlier save time
            SYSTEMDATA systemData = SystemData;
            systemData.SaveTime = saveTime;
            SystemData = systemData;
        }
    }
